ALTER TABLE users ADD COLUMN password_hash TEXT;
ALTER TABLE users ADD COLUMN tree_visible BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE calendar_events(id SERIAL PRIMARY KEY,album_id INTEGER NOT NULL REFERENCES albums(id),user_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,event_on DATE NOT NULL,event_time TIME,kind TEXT NOT NULL CHECK(kind IN ('birthday','meetup','celebration')),annually BOOLEAN NOT NULL DEFAULT false,description TEXT NOT NULL DEFAULT '',deleted_at TIMESTAMPTZ);
CREATE TABLE family_links(id SERIAL PRIMARY KEY,family_id INTEGER NOT NULL REFERENCES families(id),parent_id INTEGER NOT NULL REFERENCES users(id),child_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('parent','partner')),created_by INTEGER REFERENCES users(id),deleted_at TIMESTAMPTZ,CHECK(parent_id<>child_id),UNIQUE(family_id,parent_id,child_id,kind));
CREATE TABLE voice_notes(id SERIAL PRIMARY KEY,media_id INTEGER NOT NULL REFERENCES media(id),user_id INTEGER NOT NULL REFERENCES users(id),storage_key UUID UNIQUE NOT NULL,caption TEXT NOT NULL DEFAULT '',duration REAL NOT NULL CHECK(duration>0 AND duration<=60),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE media_places(media_id INTEGER PRIMARY KEY REFERENCES media(id) ON DELETE CASCADE,region TEXT NOT NULL CHECK(region IN ('marmara','ege','akdeniz','karadeniz','icanadolu','dogu','guneydogu')),city TEXT NOT NULL DEFAULT '',created_by INTEGER REFERENCES users(id));
CREATE TABLE challenges(id SERIAL PRIMARY KEY,album_id INTEGER NOT NULL REFERENCES albums(id),created_by INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('photo','drawing','quiz')),ends_on DATE NOT NULL,closed_at TIMESTAMPTZ);
CREATE TABLE challenge_entries(id SERIAL PRIMARY KEY,challenge_id INTEGER NOT NULL REFERENCES challenges(id),user_id INTEGER NOT NULL REFERENCES users(id),media_id INTEGER NOT NULL REFERENCES media(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,UNIQUE(challenge_id,user_id));
CREATE TABLE challenge_votes(challenge_id INTEGER NOT NULL REFERENCES challenges(id),user_id INTEGER NOT NULL REFERENCES users(id),entry_id INTEGER NOT NULL REFERENCES challenge_entries(id),PRIMARY KEY(challenge_id,user_id));
CREATE TABLE challenge_questions(id SERIAL PRIMARY KEY,challenge_id INTEGER NOT NULL REFERENCES challenges(id),prompt TEXT NOT NULL,options JSONB NOT NULL,correct_index INTEGER NOT NULL CHECK(correct_index BETWEEN 0 AND 3));
CREATE TABLE challenge_attempts(question_id INTEGER NOT NULL REFERENCES challenge_questions(id),user_id INTEGER NOT NULL REFERENCES users(id),chosen_index INTEGER NOT NULL CHECK(chosen_index BETWEEN 0 AND 3),PRIMARY KEY(question_id,user_id));
CREATE INDEX calendar_album_idx ON calendar_events(album_id,event_on) WHERE deleted_at IS NULL;
CREATE INDEX voice_media_idx ON voice_notes(media_id) WHERE deleted_at IS NULL;
